<section class="form-section"><header><h2><?= esc(lang('UI.settingsEmailSettings')) ?></h2></header><form data-settings-config="email" data-settings-form><div class="settings-channel-fields"><div class="form-field setting-smtp_host"><label for="smtp_host"><?= esc(lang('TenantMisc.smtpHost')) ?></label><input id="smtp_host" name="smtp_host" type="text" value="<?= esc($email_config['smtp_host']??'','attr') ?>"></div><div class="form-field setting-smtp_port"><label for="smtp_port"><?= esc(lang('TenantMisc.port')) ?></label><input id="smtp_port" name="smtp_port" type="number" value="<?= esc($email_config['smtp_port']??'587','attr') ?>"></div><div class="form-field setting-smtp_crypto"><label for="smtp_crypto"><?= esc(lang('TenantMisc.encryption')) ?></label><select id="smtp_crypto" name="smtp_crypto"><option value="tls" <?= ($email_config['smtp_crypto']??'tls')==='tls'?'selected':'' ?>>TLS</option><option value="ssl" <?= ($email_config['smtp_crypto']??'tls')==='ssl'?'selected':'' ?>>SSL</option></select></div><div class="form-field setting-smtp_user"><label for="smtp_user"><?= esc(lang('TenantMisc.user')) ?></label><input id="smtp_user" name="smtp_user" type="text" value="<?= esc($email_config['smtp_user']??'','attr') ?>"></div><div class="form-field setting-smtp_pass"><label for="smtp_pass"><?= esc(lang('TenantMisc.pass')) ?></label><input id="smtp_pass" name="smtp_pass" type="password" autocomplete="new-password"><p><?= esc(lang('TenantMisc.leaveBlankKeepPassword')) ?></p></div></div><p class="settings-feedback" role="status" data-settings-feedback></p><footer class="settings-save"><button type="submit" class="button primary" <?= $settingsEdit?'':'disabled' ?>><span><?= esc(lang('UI.settingsSaveSmtp')) ?></span></button></footer></form></section>
